:host {
    --topbar-h: 56px;
    --sidebar-w: 260px;
    --topbar-bg: #ffffff;
    --topbar-border: #e5e7eb;
    --topbar-fg: #0f172a;
    --sidebar-bg: #f8fafc;
    --sidebar-border: #e5e7eb;
    --main-bg: #ffffff;
    --accent: var(--primary, #6366f1);
    --duration: 220ms;
    --ease: cubic-bezier(0.22, 1, 0.36, 1);

    display: block;
    min-height: 100vh;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    color: var(--topbar-fg);
    background: var(--main-bg);
}

.topbar {
    position: sticky;
    top: 0;
    z-index: 50;
    display: flex;
    align-items: center;
    gap: 1rem;
    height: var(--topbar-h);
    padding: 0 1.25rem;
    background: var(--topbar-bg);
    border-bottom: 1px solid var(--topbar-border);
    backdrop-filter: saturate(180%) blur(6px);
}

.toggle {
    all: unset;
    display: none;
    cursor: pointer;
    padding: .35rem;
    border-radius: 8px;
    color: inherit;
    transition: background var(--duration) var(--ease);
}
.toggle:hover { background: rgba(0,0,0,.05); }

.brand {
    font-weight: 700;
    font-size: 1rem;
    letter-spacing: -0.01em;
    flex: 0 0 auto;
    min-width: 0;
}
.brand ::slotted(*) { margin: 0; font: inherit; color: inherit; }

.top-links {
    flex: 1 1 auto;
    display: flex;
    align-items: center;
    gap: 1.25rem;
    margin-left: 1rem;
    min-width: 0;
    overflow: hidden;
}
.top-links ::slotted(*) {
    color: color-mix(in srgb, currentColor 70%, transparent);
    text-decoration: none;
    font-size: .9rem;
    transition: color var(--duration) var(--ease);
}
.top-links ::slotted(*:hover) { color: var(--accent); }

.top-actions {
    display: flex;
    align-items: center;
    gap: .5rem;
    flex: 0 0 auto;
}

.shell {
    display: grid;
    grid-template-columns: var(--sidebar-w) 1fr;
    min-height: calc(100vh - var(--topbar-h));
}

.sidebar {
    position: sticky;
    top: var(--topbar-h);
    align-self: start;
    height: calc(100vh - var(--topbar-h));
    overflow-y: auto;
    background: var(--sidebar-bg);
    border-right: 1px solid var(--sidebar-border);
}
.sidebar-inner {
    padding: 1.25rem 1rem;
    display: flex;
    flex-direction: column;
    gap: .25rem;
}

.backdrop {
    display: none;
    position: fixed;
    inset: var(--topbar-h) 0 0 0;
    background: rgba(0,0,0,.35);
    z-index: 40;
    opacity: 0;
    transition: opacity var(--duration) var(--ease);
}

.main {
    min-width: 0;
    padding: 2rem clamp(1rem, 3vw, 2.5rem);
    background: var(--main-bg);
}

:host([variant="dark"]) {
    --topbar-bg: #0f172a;
    --topbar-border: #1e293b;
    --topbar-fg: #e2e8f0;
    --sidebar-bg: #0b1220;
    --sidebar-border: #1e293b;
    --main-bg: #0f172a;
}
:host([variant="dark"]) .toggle:hover { background: rgba(255,255,255,.08); }

@media (max-width: 960px) {
    .toggle { display: inline-flex; }
    .shell { grid-template-columns: 1fr; }
    .sidebar {
        position: fixed;
        top: var(--topbar-h);
        left: 0;
        width: min(80vw, 320px);
        z-index: 45;
        transform: translateX(-100%);
        transition: transform var(--duration) var(--ease);
        box-shadow: 2px 0 24px -8px rgba(0,0,0,.2);
    }
    :host([sidebar-open]) .sidebar { transform: translateX(0); }
    :host([sidebar-open]) .backdrop { display: block; opacity: 1; }
}

@media (prefers-reduced-motion: reduce) { :host { --duration: 0ms; } }

blocs/navigation/core/doc-prev-next/Bloc.content:
import template from "./template.html" with { type: "text" };
import css from "./style.css" with { type: "text" };
import { Component } from "@bernouy/components/base";

export class Bloc extends Component {
    static observedAttributes = ["prev-href", "next-href"];
    constructor() {
        super({ css, template });
    }
    connectedCallback() {
        this._sync();
    }
    attributeChangedCallback() {
        this._sync();
    }
    _sync() {
        const prev = this.shadowRoot?.querySelector("a.prev");
        const next = this.shadowRoot?.querySelector("a.next");
        const prevHref = this.getAttribute("prev-href");
        const nextHref = this.getAttribute("next-href");
        if (prev) {
            if (prevHref) {
                prev.setAttribute("href", prevHref);
            } else {
                prev.removeAttribute("href");
            }
        }
        if (next) {
            if (nextHref) {
                next.setAttribute("href", nextHref);
            } else {
                next.removeAttribute("href");
            }
        }
    }
}

customElements.define("BE5_TAG_TO_BE_REPLACED", Bloc);

